const e=[{id:"donut-crown-sepsis-whore",name:"Enchanted Crown of the Sepsis Whore",owner:"donut",category:"wearable",rarity:"legendary",description:"A tiara granting +5 INT and +5 Good First Impression, plus a 15% chance to inflict Sepsis on hit. Awarded for being the first cat ever to enter the dungeon.",acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"tiara",fate:{status:"destroyed",spoiler:{book:2},note:"Shattered by the third magical foreshock on the stairs down from Floor 3."}},{id:"carl-trollskin-shirt",name:"Enchanted Trollskin Shirt of Pummeling",owner:"carl",category:"armor",rarity:"gold",description:"Grants +7 Regeneration and negates melee debuffs — Stun, Knockback, Disarm, and Out-of-Breath. From the same gold apparel box as the cloak.",acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"shirt"},{id:"carl-nightgaunt-cloak",name:"Enchanted Nightgaunt Cloak of Stoutness",owner:"carl",category:"armor",rarity:"gold",description:`A hooded cloak of demon-wing hide. +4 CON, poison and ice resistance, and Anti-Piercing. Reward for the "Why Aren't You Wearing Pants?" achievement.`,acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"cloak"},{id:"carl-splatter-skunk-toe-ring",name:"Enchanted Toe Ring of the Splatter Skunk",owner:"carl",category:"wearable",rarity:"gold",description:'+3 STR and grants Powerful Strike. Reward for the "Podophilia" achievement — smushing a goblin barefoot.',acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"toe-ring"},{id:"carl-goblin-pass-tattoo",name:"Goblin Pass Tattoo",owner:"carl",category:"wearable",rarity:"silver",description:`A tattoo that gets Carl into the goblins' neighborhood without a fight. Awarded in a silver goblin box for the "Boom!" achievement, after a Murder Dozer's boiler blew up outside the guild hall; it pays off at the goblin workshop.`,acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"tattoo"},{id:"carl-silver-ring-con-1",name:"Silver Ring of Constitution (+1 CON)",owner:"carl",category:"wearable",rarity:"silver",description:"A stat-boosting ring, +1 CON, from the silver adventurer box awarded for finding a first safe room.",acquiredAtStopId:"floor-1-stop-11",spoiler:{book:1},glyphId:"ring-silver"},{id:"donut-slate-butterfly-talisman",name:"Talisman of the Slate Butterfly",owner:"donut",category:"wearable",rarity:"gold",description:"A talisman Donut wears on her collar, from a gold box for being among the first hundred crawlers to level Magic Missile to 3.",acquiredAtStopId:"floor-1-stop-11",spoiler:{book:1},glyphId:"talisman"},{id:"donut-magic-missile-tome",name:"Tome of Magic Missile",owner:"donut",category:"spell-book",rarity:"silver",description:"Teaches Magic Missile — Donut's first offensive spell.",acquiredAtStopId:"floor-1-stop-2",spoiler:{book:1},glyphId:"tome-missile"},{id:"carl-goblin-copper-chopper",name:"Goblin Copper Chopper",owner:"carl",category:"other",description:"A steam-powered copper-scrap motorcycle with a detachable sidecar, built by goblin engineers in exchange for two baggies of Bad Llama meth. Carl rides it; Donut takes the sidecar.",acquiredAtStopId:"floor-1-stop-12",spoiler:{book:1},glyphId:"copper-chopper"},{id:"carl-spiked-kneepads",name:"Enchanted Spiked Kneepads of the Shade Gnoll Riot Forces",owner:"carl",category:"armor",description:"From a gold crowd-control box for the dynamite blast that killed a roomful of Scatterers inside the Hoarder's lair: 10% damage reflection, and it cancels momentum-based attacks.",acquiredAtStopId:"floor-1-stop-4",spoiler:{book:1},glyphId:"kneepads"},{id:"donut-torch-spell",name:"Torch Spell",owner:"donut",category:"spell-book",description:"A utility light spell — another boss-box reward for the Hoarder fight.",acquiredAtStopId:"floor-1-stop-4",spoiler:{book:1},glyphId:"tome-torch"},{id:"carl-desperado-pass-tattoo",name:"Desperado Pass Tattoo",owner:"carl",category:"wearable",description:"A tattoo granting Desperado Club membership — mutually exclusive with the Vanquisher pass.",acquiredAtStopId:"floor-1-stop-5",spoiler:{book:1},glyphId:"desperado-tattoo"},{id:"donut-desperado-pass-tattoo",name:"Desperado Pass Tattoo",owner:"donut",category:"wearable",description:"A tattoo granting Desperado Club membership — mutually exclusive with the Vanquisher pass.",acquiredAtStopId:"floor-1-stop-5",spoiler:{book:1},glyphId:"desperado-tattoo"},{id:"carl-silver-ring-con-2",name:"Silver Ring of Constitution (+2 CON)",owner:"carl",category:"wearable",description:"A second stat-boosting ring, +2 CON.",acquiredAtStopId:"floor-1-stop-5",spoiler:{book:1},glyphId:"ring-silver"},{id:"donut-fae-scale-crupper",name:"Enchanted Fae Scale Quadruped Crupper of the Fleet",owner:"donut",category:"armor",description:"A harness-style armor piece fitted for a quadruped.",acquiredAtStopId:"floor-1-stop-5",spoiler:{book:1},glyphId:"crupper"},{id:"donut-dex-bracelet",name:"Bracelet of Dexterity",owner:"donut",category:"wearable",description:"A stat-boosting bracelet, +2 DEX, from the Juicer fight.",acquiredAtStopId:"floor-1-stop-7",spoiler:{book:1},glyphId:"obsidian-bracelet"},{id:"carl-war-gauntlet-grull",name:"Enchanted War Gauntlet of the Exalted Grull",owner:"carl",category:"weapon",description:'A wrist bracer that becomes a spiked orcish gauntlet when Carl makes a fist: +3 STR, +1 DEX, +2 Iron Punch, and a small stun chance, without losing his bare-knuckle bonus. Its warning: hitting a follower of the war god Grull can turn them into Grull himself. Reward for the "Two Chicks at the Same Time" achievement in the Juicer fight.',acquiredAtStopId:"floor-1-stop-7",spoiler:{book:1},glyphId:"gauntlet"},{id:"carl-shuriken-bloodlust",name:"Enchanted Shuriken of Bloodlust",owner:"carl",category:"weapon",description:"A boss-box reward for defeating the Juicer.",acquiredAtStopId:"floor-1-stop-7",spoiler:{book:1},glyphId:"shuriken"},{id:"donut-puddle-jumper-tome",name:"Tome of Puddle Jumper",owner:"donut",category:"spell-book",rarity:"bronze",description:"Teaches Puddle Jumper, a short-range group teleport spell.",acquiredAtStopId:"floor-1-stop-7",spoiler:{book:1},glyphId:"tome-jump"},{id:"carl-misc-effects-ball-of-swine",name:"Recovered Effects",owner:"carl",category:"other",description:"A grab bag pulled from the wreckage after the Ball of Swine fight — blood-soaked tuxedos, a ruby necklace, a pig harness, and shuriken remnants.",acquiredAtStopId:"floor-1-stop-9",spoiler:{book:1},glyphId:"grab-bag"},{id:"donut-novelty-item",name:"Recovered Novelty Item",owner:"donut",category:"other",description:"Recovered from the wreckage after the Ball of Swine fight — exactly as undignified as it sounds.",acquiredAtStopId:"floor-1-stop-9",spoiler:{book:1},glyphId:"duct-tape"},{id:"donut-hole-spell",name:"Hole",owner:"donut",category:"spell-book",description:"Donut's first spell picked up on the Iron Tangle — punches a hole through whatever it targets.",acquiredAtStopId:"floor-4-stop-2",spoiler:{book:3},glyphId:"tome-hole"},{id:"carl-dungeon-anarchists-cookbook",name:"The Dungeon Anarchist's Cookbook (24th Edition)",owner:"carl",category:"cookbook",rarity:"celestial",description:"Invisible to the dungeon's producers and viewers, visible only to the System AI — an underground survival guide passed hand to hand between crawlers, each holder adding their own entries for the next. Carl wins it as the prize of a viewer-voted Prize Carousel event, inheriting the 24th Edition; what he writes in it becomes the 25th.",acquiredAtStopId:"floor-4-stop-4",spoiler:{book:3},glyphId:"anarchist-cookbook"},{id:"donut-prism-goggles",name:"Prism Industries Capacitating and Focusing Goggles",owner:"donut",category:"wearable",rarity:"platinum",description:"Sponsor-gifted sunglasses that let Donut see through more than the obvious — she uses them to catch an invisible attack aimed at Katia during the Vermillion Line rescue.",acquiredAtStopId:"floor-4-stop-8",spoiler:{book:3},glyphId:"goggles"},{id:"carl-ring-divine-suffering",name:"Enchanted Night Wyrm's Ring of Divine Suffering",owner:"carl",category:"wearable",rarity:"legendary",description:'+5% to all stats and the Marked for Death skill: the wearer marks a crawler at full health, gains a permanent stat point when that mark dies, and cannot heal at all until it does. Handed to Carl by Frank Q as an act of revenge, not friendship — "a lottery win that ruins whoever holds it."',acquiredAtStopId:"floor-4-stop-11",spoiler:{book:3},glyphId:"ring-wyrm",fate:{status:"kept",spoiler:{book:3},note:"A curse rather than a boon — Carl keeps it, and keeps paying for it."}},{id:"carl-pedicure-kit-of-the-sylph",name:"Enchanted Pedicure Kit of the Sylph",owner:"carl",category:"toolkit",rarity:"platinum",description:"Twelve metal tools; used barefoot for ~15 minutes in a safe room, it activates a 30-hour buff: +15% barefoot attack damage, +3 Smush Skill, Unbreakable feet, and a 5-second trap-alarm delay. Every bonus requires staying barefoot.",acquiredAtStopId:"floor-2-stop-1",spoiler:{book:1},glyphId:"pedicure-kit"},{id:"carl-cheat-code-potion",name:"Cheat Code Potion",owner:"carl",category:"potion",rarity:"silver",description:"Grants +3 levels to one recently-used combat or magic skill — took his Pugilism to 10. A flashing ~17-minute expiry timer means it cannot be hoarded.",acquiredAtStopId:"floor-2-stop-1",spoiler:{book:1},glyphId:"potion-timer"},{id:"donut-second-chance-tome",name:"Tome of Second Chance",owner:"donut",category:"spell-book",description:"A necromancy spell: raises a dead monster as an undead minion at a third of its former level for a few minutes. Delivered by her new safe-room mailbox — the first spellbook from her Dungeon Book of the Floor Club membership.",acquiredAtStopId:"floor-2-stop-1",spoiler:{book:1},glyphId:"tome-second-chance"},{id:"carl-slingshot",name:"Slingshot and rocks",owner:"carl",category:"weapon",description:"Unenchanted and weak, looted off a Clurichaun. Carl keeps using it anyway.",acquiredAtStopId:"floor-2-stop-3",spoiler:{book:1},glyphId:"slingshot"},{id:"carl-jug-o-boom",name:"Carl's Jug O'Boom",owner:"carl",category:"weapon",description:"A moonshine jug packed with Goblin Oil and corked with a torch — his own invention after catching the Taint. The system names it after him: he earns one gold coin for every kill any other crawler ever makes with it.",acquiredAtStopId:"floor-2-stop-3",spoiler:{book:1},glyphId:"jug"},{id:"carl-bigboi-boxers",name:"Enchanted BigBoi Boxers",owner:"carl",category:"wearable",rarity:"bronze",description:"White boxers covered in little red hearts. +2 CON, and a once-per-30-hours Level 15 Protective Shell. His old boxers didn't survive the Krakaren Clone's blast.",acquiredAtStopId:"floor-2-stop-5",spoiler:{book:1},glyphId:"boxers",revisions:[{spoiler:{book:2},patch:{description:"White boxers covered in little red hearts, upgraded once. Now +5 CON, +5 DEX and +5 INT on top of the original once-per-30-hours Level 15 Protective Shell, and carrying the Freeballing benefit: double damage and a fifth again as much experience on anything he does below the waist, provided he wears no more than one layer over the crotch. The system's own note is that he won't be getting trousers anytime soon."}}]},{id:"donut-fur-brush",name:"Enchanted Fur Brush of the Ecclesiastic",owner:"donut",category:"toolkit",rarity:"bronze",description:"Someone else brushing her fur for ten straight minutes grants +2 CON for a 30-hour day.",acquiredAtStopId:"floor-2-stop-5",spoiler:{book:1},glyphId:"fur-brush"},{id:"carl-confusing-fog-scroll",name:"Confusing Fog Scroll",owner:"carl",category:"consumable",rarity:"gold",description:"Fills an area with fog that blinds mobs but stays translucent to crawlers. From the same gold crowd-control box as the kneepads; Carl wastes several in the Juicer fight.",acquiredAtStopId:"floor-1-stop-4",spoiler:{book:1},glyphId:"scroll-fog"},{id:"carl-goblin-smoke-bomb",name:"Goblin Smoke Bomb",owner:"carl",category:"consumable",description:"An opaque, stinking smoke bomb — a ten-meter radius, three minutes of cover.",acquiredAtStopId:"floor-2-stop-5",spoiler:{book:1},glyphId:"smoke-bomb"},{id:"carl-fireball-or-custard",name:"Fireball or Custard?",owner:"carl",category:"consumable",rarity:"platinum",description:"A five-spot scratch card: each spot is a coin flip between a Level 15 Fireball and a healing custard glob, delivered to the nearest tagged mob.",acquiredAtStopId:"floor-2-stop-7",spoiler:{book:1},glyphId:"scratch-card"},{id:"donut-dungeon-gold-rush",name:"Dungeon Gold Rush",owner:"donut",category:"consumable",rarity:"platinum",description:"A scratch-off lottery ticket with wildly mismatched outcomes, from a gold-coin windfall to splitting the target mob in two. Carl tells her not to use it.",acquiredAtStopId:"floor-2-stop-7",spoiler:{book:1},glyphId:"lottery-ticket"},{id:"carl-gorgon-marital-aid",name:"Gorgon Marital Aid",owner:"carl",category:"toolkit",rarity:"silver",description:"A spatula-shaped workbench tool that fuses joints and adds plasticity without weakening the material.",acquiredAtStopId:"floor-2-stop-9",spoiler:{book:1},glyphId:"spatula"},{id:"carl-proximity-trigger",name:"Proximity Trigger",owner:"carl",category:"toolkit",rarity:"gold",description:"A dime-sized trigger on a wire, set at a Sapper's Table with a countdown and a mob-type filter. Ten of them become some of his most valuable gear.",acquiredAtStopId:"floor-2-stop-9",spoiler:{book:1},glyphId:"trigger"},{id:"carl-tactical-boots",name:"Tactical boots",owner:"carl",category:"wearable",description:"A parting gift from Prince Maestro, meant to mock his barefoot build. Carl thanks him with no intention of ever wearing them.",acquiredAtStopId:"floor-2-stop-10",spoiler:{book:1},glyphId:"boots"},{id:"carl-determine-value-potion",name:"Skill Potion of Determine Value",owner:"carl",category:"potion",rarity:"bronze",description:`A boss-box reward from Ralph. Raises the Determine Value skill to level 3, which unlocks the inventory's "History" tab.`,acquiredAtStopId:"floor-2-stop-13",spoiler:{book:1}},{id:"carl-valtay-corporation-effects",name:"Recovered Valtay Corporation Effects",owner:"carl",category:"other",description:"Three items traced through the new Inventory History to Agatha's cart: an inter-tunnel communications relay the system flags as illegal to operate, a personal shield, and a pulse pistol.",acquiredAtStopId:"floor-2-stop-13",spoiler:{book:1},glyphId:"tech-crate"},{id:"carl-primal-race",name:"Primal",owner:"carl",category:"other",description:"The race Carl takes on the Third Floor: a point off every base stat, in exchange for being able to train any skill far past its normal ceiling. A deliberately bad trade in the short term and the foundation of everything he does afterward.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"race-primal"},{id:"carl-compensated-anarchist",name:"Compensated Anarchist",owner:"carl",category:"other",description:"A rare and exclusive class, unlocked by holding Explosives Handling at level 5 with half a trillion views. Grants Bomb Surgeon, Trap Engineer, Unarmed Combat, Hide in Shadows, Find Trap, Backfire and Escape Plan, the Fear spell, and membership of the Desperado Club. Carl picks it off a menu; nobody assigns it to him.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"class-anarchist",fate:{status:"upgraded",spoiler:{book:5},note:"Specializes into Agent Provocateur on the Sixth Floor."}},{id:"donut-cat-race",name:"Cat",owner:"donut",category:"other",description:"Donut stays what she already was, which turns out to be the strong play.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"race-cat"},{id:"donut-former-child-actor",name:"Former Child Actor",owner:"donut",category:"other",description:"A rare subclass unlocked by the Cut! achievement at a trillion views. Grants Character Actor, the Cockroach survival skill, +10 charisma and faster charisma-skill growth, immunity to poison and disease — and the Manager Benefit, which conscripts Mordecai whether he likes it or not.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"class-actor",fate:{status:"upgraded",spoiler:{book:5},note:"Becomes Legendary Diva, and the spell-singing that comes with it."}},{id:"party-manager-benefit",name:"Mordecai's Manager Benefit",owner:"party",category:"other",description:"A rider on Donut's class rather than an item: her manager teleports to any safe room the party enters, for the rest of the dungeon. It is the mechanism that keeps Mordecai with them long after a guide would normally be gone.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"manager-benefit"},{id:"donut-artist-alley-mogul",name:"Artist Alley Mogul",owner:"donut",category:"other",description:"Donut's Third Floor Character Actor specialty: +5 dexterity, dodge trained well past its cap, a sales bonus, and interest on coin carried down. It is a floor-scoped title, not a permanent one.",acquiredAtStopId:"floor-3-stop-1",spoiler:{book:2},glyphId:"class-mogul",fate:{status:"lost",spoiler:{book:2},note:"Expires on the descent to Floor 4, taking its five points of dexterity with it."}},{id:"carl-big-top-ticket",name:"Big Top Ticket",owner:"carl",category:"other",description:"Looted from Terror the Clown. It buys guaranteed safe passage through the circus's public areas — and only the public areas, which is the part that matters once Carl is standing in the center ring.",acquiredAtStopId:"floor-3-stop-3",spoiler:{book:2},glyphId:"ticket",fate:{status:"consumed",spoiler:{book:2},note:"Shown at the tent flap to get inside the Big Top."}},{id:"carl-earth-hobby-cesta-punta",name:"Cesta Punta",owner:"carl",category:"other",description:"The skill that comes out of Carl's Earth Hobby Potion: the Basque game played with a curved wicker scoop strapped to the arm. It looks like a joke prize for weeks, and it is the reason the audience later votes him the single most useful thing he owns.",acquiredAtStopId:"floor-3-stop-4",spoiler:{book:2},glyphId:"cesta-ball"},{id:"donut-earth-hobby-scutelliphily",name:"Scutelliphily",owner:"donut",category:"other",description:"Donut's Earth hobby, from the matching potion: patch collecting. She takes it entirely seriously.",acquiredAtStopId:"floor-3-stop-4",spoiler:{book:2},glyphId:"patch"},{id:"carl-earth-box-cactus",name:"Small cactus, in a clay pot",owner:"carl",category:"other",description:"Eight inches of houseplant, out of a Silver Earth Box awarded for taking an Earth class — alongside a stack of Louis L'Amour westerns. He keeps it.",acquiredAtStopId:"floor-3-stop-4",spoiler:{book:2},glyphId:"cactus"},{id:"donut-clockwork-triplicate",name:"Clockwork Triplicate",owner:"donut",category:"spell-book",description:"The Third Floor's Dungeon Book of the Floor Club spell: twenty-six mana to put two more physical copies of a pet or minion on the field. Three Mongos, each carrying dynamite, is a tactic the floor does not survive.",acquiredAtStopId:"floor-3-stop-4",spoiler:{book:2},glyphId:"tome-clockwork"},{id:"donut-anklet-fallen-oak",name:"Enchanted Anklet of the Fallen Oak",owner:"donut",category:"wearable",description:"Taken from the corpse of a crawler in the Bautista family party. +1 dexterity, +1 constitution, and a bonus to Double Tap. Its name later convinces a cult that Donut is something they have been waiting for.",acquiredAtStopId:"floor-3-stop-5",spoiler:{book:2},glyphId:"anklet"},{id:"carl-silver-strength-rings",name:"Silver Rings of +2 Strength (pair)",owner:"carl",category:"wearable",rarity:"silver",description:"Two rings off the same dead party: four points of strength between them, several times what Primal took.",acquiredAtStopId:"floor-3-stop-5",spoiler:{book:2},glyphId:"ring-pair"},{id:"carl-wisp-armor",name:"Wisp Armor",owner:"carl",category:"spell-book",description:"A five-mana shield blocking three quarters of incoming magic damage, and — the reason he reads it when he does — immunity to mind control. He casts it moments before eating a cone of parasitic worms on purpose.",acquiredAtStopId:"floor-3-stop-9",spoiler:{book:2},glyphId:"tome-wisp"},{id:"carl-scroll-of-upgrade",name:"Scroll of Upgrade",owner:"carl",category:"other",description:"Out of a Platinum Quest Box, with a short shelf life. Carl spends it on his underwear, which is both the funniest and the correct decision.",acquiredAtStopId:"floor-3-stop-11",spoiler:{book:2},glyphId:"scroll-upgrade",fate:{status:"consumed",spoiler:{book:2},note:"Used on the Enchanted BigBoi Boxers."}},{id:"mongo-fang-caps",name:"Enchanted Fang Caps of the Expectorating Tizheruk",owner:"donut",category:"wearable",description:"A Fleeting Item out of Donut's Platinum Quest Box, fitted to Mongo: half again as much bite damage, with a chance of poison and a chance of paralysis on the bite.",acquiredAtStopId:"floor-3-stop-11",spoiler:{book:2},glyphId:"fang-caps"},{id:"carl-casino-chip",name:"Casino Chip (100,000 gold)",owner:"carl",category:"other",description:"A comp chip from a Platinum Lucky Bastard Box, earned for surviving a spell far above his level. Non-transferable, and playable only at the high roller tables.",acquiredAtStopId:"floor-3-stop-11",spoiler:{book:2},glyphId:"casino-chip"},{id:"carl-alchemy-starter-kit",name:"Alchemy Starter Kit",owner:"carl",category:"toolkit",description:"Bought from the Desperado Club pharmacist, with two vials of Bijol sap. Carl gets his alchemy to level 3 brewing hangover cures for Mordecai.",acquiredAtStopId:"floor-3-stop-12",spoiler:{book:2},glyphId:"alchemy-kit"},{id:"carl-hobgoblin-explosives",name:"Hobgoblin Hob-Lobbers and dynamite",owner:"carl",category:"weapon",description:"Twenty-five fused Hob-Lobbers for five hundred gold, plus a case of dynamite, from a hobgoblin in the Silk Road. The dynamite goes into a magistrate's bookshelves days before anyone needs it to.",acquiredAtStopId:"floor-3-stop-12",spoiler:{book:2},glyphId:"hob-lobber"},{id:"carl-xistera",name:"Carl's Xistera",owner:"carl",category:"weapon",description:"A two-foot wicker scoop mounted to hand and forearm, folding down into a bracer. Summoned items drop straight into it, and it throws a Hob-Lobber at something near two hundred and fifty miles an hour. His first Fan Box, and the audience chose it precisely because of the hobby potion.",acquiredAtStopId:"floor-3-stop-13",spoiler:{book:2},glyphId:"xistera"},{id:"donut-beatrice-and-brad-photo",name:"Framed picture of Beatrice and Brad",owner:"donut",category:"other",description:"Donut's Fan Box, opened alongside Carl's. It is a photograph of two cats, and she is delighted.",acquiredAtStopId:"floor-3-stop-13",spoiler:{book:2},glyphId:"photo-frame"},{id:"carl-gate-pass",name:"Gate Pass",owner:"carl",category:"other",description:"Off GumGum's body. It makes Carl untouchable by the township's guards while he is inside its limits — which is how he walks a corpse into the magistrate's office and back out again.",acquiredAtStopId:"floor-3-stop-13",spoiler:{book:2},glyphId:"gate-pass"},{id:"carl-mysterious-letter",name:"Mysterious Letter",owner:"carl",category:"other",description:"Also off GumGum's body, and unsellable: a scroll in necromantic script carrying a Suppurating Eye spell. Carl works out that a thing which watches can also be a thing that draws someone to look.",acquiredAtStopId:"floor-3-stop-13",spoiler:{book:2},glyphId:"letter-blood",fate:{status:"consumed",spoiler:{book:2},note:"Cast as bait to put Miss Quill in front of her own bookshelves."}},{id:"carl-kimaris-figure",name:"Stuffed Kimaris Figure, in a Sheol Glass Reaper Case",owner:"carl",category:"other",description:"Pocketed from the wreck of the magistrate's desk — a stuffed toy with its tags still on, sealed in a glass case. Rated Unique, and by some measures the single most valuable thing Carl owns. The case matters more than the toy, though nobody knows that yet.",acquiredAtStopId:"floor-3-stop-16",spoiler:{book:2},glyphId:"stuffed-figure"},{id:"carl-quiet-slippers",name:"Quiet Slippers",owner:"carl",category:"wearable",rarity:"bronze",description:"Out of a Bronze Assassin's Box, with a set of antidotes. Awarded for a killing the system decided to call an assassination.",acquiredAtStopId:"floor-3-stop-16",spoiler:{book:2},glyphId:"slippers"},{id:"carl-necklace-haute-bourgeoisie",name:"Enchanted Necklace of the Haute Bourgeoisie",owner:"carl",category:"wearable",rarity:"platinum",description:"The contents of a Platinum Tyrant Box, awarded for killing an acting magistrate and inheriting the office. Earned on the Third Floor and not actually opened until the Fourth.",acquiredAtStopId:"floor-3-stop-16",spoiler:{book:2},glyphId:"necklace"},{id:"carl-doomsday-scenario",name:"Carl's Doomsday Scenario",owner:"carl",category:"weapon",description:"A soul crystal caught mid-detonation inside a sealed glass case and pulled into inventory, where it stays — because it goes off the millisecond it leaves. Forty-five kilometers of blast radius that can no longer be stabilized, and the book is named after it.",acquiredAtStopId:"floor-3-stop-17",spoiler:{book:2},glyphId:"soul-crystal"},{id:"carl-toe-ring-leprous-bandit",name:"Enchanted Toe Ring of the Leprous Bandit",owner:"carl",category:"wearable",description:"Sticky Feet and Super Spreader in one ring, out of a Platinum Spicy Box for Smushed for Daddy, the achievement for being stepped on by Grull back on Floor 4.",acquiredAtStopId:"floor-5-stop-2",spoiler:{book:4},glyphId:"toe-ring-leprous"},{id:"carl-pawnas-tears",name:"Pawna's Tears",owner:"carl",category:"potion",rarity:"legendary",description:"Earned as a Legendary Deity's Box back on Floor 4, opened here alongside the rest of that floor's backlog.",acquiredAtStopId:"floor-5-stop-2",spoiler:{book:4},glyphId:"pawnas-tears",fate:{status:"kept",spoiler:{book:4},note:"Handed to Donut on the next floor rather than used here."}},{id:"donut-scrolls-water-breathing",name:"Scroll of Water Breathing",owner:"donut",category:"other",description:"One scroll from the Floor 4 backlog boxes, which Donut swears on the spot she'll never use: cats do not swim.",acquiredAtStopId:"floor-5-stop-2",spoiler:{book:4},glyphId:"scroll-water"},{id:"carl-surefire",name:"Surefire (x25)",owner:"carl",category:"consumable",description:"Two dozen and five rounds out of a Sniper's Box, kept in reserve rather than spent immediately.",acquiredAtStopId:"floor-5-stop-2",spoiler:{book:4},glyphId:"surefire"},{id:"donut-astral-paw",name:"Astral Paw",owner:"donut",category:"spell-book",description:"The Dungeon Book of the Floor Club's Floor 5 spell. One wiki files it three books later instead, alongside her later Nekhebit-championship kit — but that's the single outlier against two independent sources placing it here, so it stays.",acquiredAtStopId:"floor-5-stop-2",spoiler:{book:4},glyphId:"tome-astral-paw"},{id:"party-royal-chariot",name:"The Royal Chariot",owner:"party",category:"other",description:"Built by Carl and Katia in Hump Town's own streets, not looted or boxed — the floor's one crafted acquisition.",acquiredAtStopId:"floor-5-stop-4",spoiler:{book:4},glyphId:"royal-chariot"},{id:"carl-toraline-root",name:"Toraline Root Vegetable",owner:"carl",category:"other",description:"A single root, sent by a pacifist-action sponsor in a Silver Benefactor Box. Looks like nothing until it becomes the one ingredient that matters at the very end of the floor.",acquiredAtStopId:"floor-5-stop-6",spoiler:{book:4},glyphId:"toraline-root",fate:{status:"consumed",spoiler:{book:4},note:"Brewed into the Phase Lava Rock Potion used to free Chris from Maggie."}},{id:"donut-gnome-farseer",name:"Enchanted Gnome Farseer",owner:"donut",category:"toolkit",description:"Lifted off Skarn's roof in ten seconds. Donut was meant to leave thirty gold behind and 'forgets'. Reads farther than anything else the party carries.",acquiredAtStopId:"floor-5-stop-6",spoiler:{book:4},glyphId:"gnome-farseer"},{id:"katia-petrify-bolts",name:"Bolts of Petrify Rock (x10)",owner:"other",category:"weapon",rarity:"silver",description:"Katia's own Silver Emergency Benefactor Box, ten bolts that turn whatever they hit to stone. Seven get used petrifying Chris Andrews, with Maggie My riding him, in Hump Town's ruined quarter.",acquiredAtStopId:"floor-5-stop-8",spoiler:{book:4},glyphId:"petrify-bolts"},{id:"carl-celestial-grenade",name:"Celestial Grenade",owner:"carl",category:"weapon",rarity:"celestial",description:"Pocketed off the ground when it drops mid-fight rather than earned outright. Its second use is the one that matters.",acquiredAtStopId:"floor-5-stop-8",spoiler:{book:4},glyphId:"celestial-grenade",fate:{status:"consumed",spoiler:{book:4},note:"Thrown to deliberately summon Emberus."}},{id:"carl-sharpening-stone",name:"Platinum Sharpening Stone",owner:"carl",category:"toolkit",rarity:"platinum",description:"Consumed on the spot upgrading the war gauntlet he's carried since Floor 1.",acquiredAtStopId:"floor-5-stop-8",spoiler:{book:4},glyphId:"sharpening-stone",fate:{status:"consumed",spoiler:{book:4},note:"Used to upgrade the War Gauntlet of the Exalted Grull."}},{id:"party-robot-donut",name:"Veriluxx Robot Donut",owner:"party",category:"other",description:"A Veriluxx RealPet double of Donut from her sponsor, built to self-destruct if tampered with. Mongo destroys the first; Veriluxx sends a replacement, and Carl rigs its battery cover to fall off at the first knock before the infomercial Loita pulls them off the floor for — condensed here rather than carried as two separate stops.",acquiredAtStopId:"floor-5-stop-8",spoiler:{book:4},glyphId:"robot-donut",fate:{status:"destroyed",spoiler:{book:4},note:"Mongo destroys the first. The replacement self-destructs off the floor during the Veriluxx shoot, when its battery cover falls away, and Loita dies."}},{id:"carl-kua-tin-rebreather",name:"Kua-Tin Rebreather",owner:"carl",category:"wearable",description:"Loita's own, taken off her body after Robot Donut goes off beside her during the Veriluxx infomercial, not long after the Air quadrant falls. Carl carries it in his waistband until he's back on the floor.",acquiredAtStopId:"floor-5-stop-9",spoiler:{book:4},glyphId:"rebreather"},{id:"party-ghazis-winding-box",name:"Ghazi's winding box",owner:"party",category:"other",description:"The piece of the Gate of the Feral Gods held in the Land quadrant — the reason the Sandcastle was fused open rather than flooded.",acquiredAtStopId:"floor-5-stop-10",spoiler:{book:4},glyphId:"winding-box"},{id:"katia-ghazis-notes",name:"Ghazi's notes",owner:"other",category:"other",description:"Taken by Katia off Ghazi himself, after she gets him out of the collapsing Sandcastle and kills him. They explain how to work the Gate.",acquiredAtStopId:"floor-5-stop-10",spoiler:{book:4},glyphId:"ghazi-notes"},{id:"carl-henriks-watch",name:"Henrik's pocket watch and note",owner:"carl",category:"other",description:"The second piece of the Gate, looted off a corpse in the water rather than handed over — Henrik never made it out of the Sea quadrant himself.",acquiredAtStopId:"floor-5-stop-13",spoiler:{book:4},glyphId:"pocket-watch"},{id:"carl-battle-rattle",name:"Enchanted Anarchist's Battle Rattle",owner:"carl",category:"wearable",rarity:"platinum",description:"A jacket out of a Platinum Spicy Box for an achievement earned surviving being partially swallowed. Stays on his back for the rest of the crawl so far.",acquiredAtStopId:"floor-5-stop-15",spoiler:{book:4},glyphId:"battle-rattle"},{id:"carl-earth-upgrade-patch",name:"Earth Upgrade Patch",owner:"carl",category:"other",description:"From the same box as the Battle Rattle, sewn onto it rather than kept loose.",acquiredAtStopId:"floor-5-stop-15",spoiler:{book:4},glyphId:"earth-patch"},{id:"carl-drakeas-kerchief",name:"Drakea's Enchanted Kerchief of Disorder",owner:"carl",category:"wearable",rarity:"gold",description:"A Gold boss box for Lusca's kill, worn as a mask rather than left in inventory.",acquiredAtStopId:"floor-5-stop-15",spoiler:{book:4},glyphId:"kerchief"},{id:"party-ring-water-breathing",name:"Ring of Water Breathing",owner:"party",category:"wearable",rarity:"gold",description:"A Gold box reward, copies of which end up on more than one party member by the time the floor ends.",acquiredAtStopId:"floor-5-stop-15",spoiler:{book:4},glyphId:"ring-water"},{id:"carl-rockards-ring",name:"Rockard's Ring of Sniping",owner:"carl",category:"wearable",description:"Pulled off Quan Ch's severed left arm after Carl tears it away as he flees. The ring turns out to be the source of Quan's kill-stealing reputation.",acquiredAtStopId:"floor-5-stop-17",spoiler:{book:4},glyphId:"ring-amber"},{id:"carl-emberus-tattoos",name:"Emberus tattoos",owner:"carl",category:"other",description:"Marks of a tithe to a god he chose to summon rather than flee, applied as the floor closes out.",acquiredAtStopId:"floor-5-stop-18",spoiler:{book:4},glyphId:"emberus-tattoo"},{id:"donut-twinkle-toes",name:"Twinkle Toes",owner:"donut",category:"spell-book",description:"A platinum quest box spell, small next to everything else the floor hands out but hers alone.",acquiredAtStopId:"floor-5-stop-18",spoiler:{book:4},glyphId:"tome-twinkle"},{id:"carl-xistera-extension",name:"Enchanted Xistera Extension Slot",owner:"carl",category:"weapon",rarity:"platinum",description:"An emergency Platinum Benefactor Box attachment for the scoop he's carried since Floor 3 — extends its throw distance and strength, and is custom-fitted for exactly the kind of decapitated love-doll head he now carries too.",acquiredAtStopId:"floor-5-stop-18",spoiler:{book:4},glyphId:"xistera-extension"},{id:"party-hunting-trophies",name:"Hunting Trophies",owner:"party",category:"other",description:"Severed hunter hands, one from each of thirty-four Hunter-Killer boxes (which also paid out roughly 595,000 gold). They are worthless if sold and serve as prize tickets at the Masquerade's Prize Counter.",glyphId:"hunter-hand",acquiredAtStopId:"floor-6-stop-3",spoiler:{book:5}},{id:"carl-guild-of-suffering-tattoo",name:"Guild of Suffering Tattoo",owner:"carl",category:"other",description:"A spiderweb tattoo from a Gold Junkie Box, granting access to the Guild of Suffering — a name that shares its 'Night Wyrm' branding with the Ring of Divine Suffering he already carries from Floor 4, likely the same cult.",rarity:"gold",glyphId:"suffering-web",acquiredAtStopId:"floor-6-stop-3",spoiler:{book:5}},{id:"donut-collar-charm",name:"Enchanted Collar Charm of the Effete Bourgeoisie",owner:"donut",category:"wearable",description:"A reward for becoming mayor of Point Mongo — grants taxes and stat bonuses befitting the office.",glyphId:"collar-charm",acquiredAtStopId:"floor-6-stop-4",spoiler:{book:5}},{id:"carl-hunter-territory-map",name:"Hunter-Territory Map",owner:"carl",category:"other",description:"A map of hunter-controlled ground, looted during Signet's return.",glyphId:"territory-map",acquiredAtStopId:"floor-6-stop-5",spoiler:{book:5}},{id:"carl-gonorrhea-arrow",name:"Arrow of Enthusiastic Double Gonorrhea",owner:"carl",category:"weapon",description:"One of several carried by The Dream's hunters for Louis. Carl later stabs Vrah with it.",glyphId:"gonorrhea-arrow",acquiredAtStopId:"floor-6-stop-5",spoiler:{book:5},fate:{status:"consumed",spoiler:{book:5},note:"Stabbed into Vrah's neck at Alucarda."}},{id:"donut-fireball-bracelet",name:"Fireball-Granting Bracelet",owner:"donut",category:"wearable",description:"Taken off a killed elf assassin during an artillery barrage; later used to level up her Laundry Day spell at the Masquerade.",glyphId:"fireball-bracelet",acquiredAtStopId:"floor-6-stop-7",spoiler:{book:5}},{id:"carl-trebuchet",name:"Venomous Elven Rock Chucker",owner:"carl",category:"weapon",description:"A hunter's own trebuchet, looted and later put to use sniping an Odious Creeper during the floor's own failed fifty-creeper world quest.",glyphId:"rock-chucker",acquiredAtStopId:"floor-6-stop-7",spoiler:{book:5}},{id:"katia-crown-of-sepsis-whore-2",name:"Crown of the Sepsis Whore",owner:"other",category:"wearable",description:"The regenerated Enchanted Crown of the Sepsis Whore, the same Fleeting crown Donut wore until it shattered leaving Floor 3. Eva wore it on her breastplate, and as Katia killed her it equipped itself on Katia's head. That puts Katia in the Blood Sultanate's line of succession alongside Donut, and only one of them can descend past the Ninth Floor.",glyphId:"tiara",acquiredAtStopId:"floor-6-stop-16",spoiler:{book:5},fate:{status:"kept",spoiler:{book:5}}},{id:"donut-hammer-of-fast-forward",name:"Enchanted Hammer of Fast Forward",owner:"donut",category:"toolkit",description:"A sponsor gift delivered to Donut via Imani ahead of the Butcher's Masquerade, stamped with a faint '7' that Carl notices but doesn't yet understand. Used by Prepotente during the Seventh Floor's opening countdown to tap the softened glass of the Pole Position Chamber, completing the fracture that brings the entire level down.",glyphId:"hammer-fast-forward",acquiredAtStopId:"floor-6-stop-14",spoiler:{book:5}},{id:"donut-stick-of-cascadias-screams",name:"Enchanted Stick of Cascadia's Screams",owner:"donut",category:"toolkit",description:"A second sponsor gift delivered to Donut, this one sent by the Apothecary through Dmitri Popov and likewise stamped with a faint '7'. Prepotente pushes it through the Pole Position Chamber's softened glass wall to complete the fracture that shatters the Seventh Floor.",glyphId:"stick-cascadias-screams",acquiredAtStopId:"floor-6-stop-14",spoiler:{book:5}},{id:"prepotente-seventh-floor-pole-position",name:"Seventh-Floor Pole Position",owner:"other",category:"other",description:"A one-per-customer Future Floor Boon bought outright by Prepotente at the Butcher's Masquerade prize counter for 30 of his 33 hunter hands — first in line, and gone from the counter immediately after him. Places its holder in a private starting chamber ahead of the general field on the Seventh Floor, which is exactly what puts Prepotente next to the level's structural weak point with time to work at it.",glyphId:"pole-position",acquiredAtStopId:"floor-6-stop-14",spoiler:{book:5},fate:{status:"consumed",spoiler:{book:5},note:"A single-use boon, spent the moment it places him in the chamber."}},{id:"donut-geraldo-totem",name:"Geraldo (T'Ghee totem)",owner:"donut",category:"other",description:"A captured Monk Seal, the Royal Court's first totem.",glyphId:"totem-geraldo",acquiredAtStopId:"floor-8-stop-3",spoiler:{book:6}},{id:"donut-raul-totem",name:"Raul (T'Ghee totem)",owner:"donut",category:"other",description:"A Red Maníseros land crab, pig-sized and armored, found meditating on a crashed U-Haul, shut inside it and beaten down until Donut could flag him. Outlasts nearly every other totem this floor.",glyphId:"totem-raul",acquiredAtStopId:"floor-8-stop-7",spoiler:{book:6},fate:{status:"kept",spoiler:{book:7},note:"Persists into book 7, upgraded to a mythic-tier totem."}},{id:"donut-shi-maria-totem",name:"Shi Maria (T'Ghee totem)",owner:"donut",category:"other",description:"A demi-god Reaper Spider, carded by consent rather than defeated, in return for the party's promise to carry her to the next floor (the Bedlam Bride escort quest).",glyphId:"totem-shi-maria",acquiredAtStopId:"floor-8-stop-8",spoiler:{book:6},fate:{status:"destroyed",spoiler:{book:6},note:"Torn up empty after Shi Maria fuses directly into Carl and binds herself there as a permanent tattoo instead — see carl-eye-of-the-bedlam-bride-tattoo."}},{id:"donut-asojano-totem",name:"Asojano (T'Ghee totem)",owner:"donut",category:"other",description:"The Orisha Lord of Smallpox, flagged as a card when his shrine goes unrepaired in the Celestial Thorn Room. Obeys once shouted at, and opens every practice bout by trying to debuff whoever is nearest.",glyphId:"totem-asojano",acquiredAtStopId:"floor-8-stop-5",spoiler:{book:6},fate:{status:"upgraded",spoiler:{book:6},note:"Fused permanently into Lazarus-A-Bang-Bang alongside the HeyZoos totem during the Phase Two deckmaster hunt; later returns as Lord of Blight - Gold Edition."}},{id:"donut-lazarus-a-bang-bang-totem",name:"Lazarus-A-Bang-Bang (T'Ghee totem)",owner:"donut",category:"other",description:"The Asojano and HeyZoos totems, fused into one card with a Combo and a Glow-Up. The fusion holds until the Phase Three fights, when Lazarus dies mid-combo and splits back into Gold Edition versions of both.",glyphId:"totem-lazarus-a-bang-bang",acquiredAtStopId:"floor-8-stop-12",spoiler:{book:6},fate:{status:"destroyed",spoiler:{book:6},note:"Killed mid-combo with Skylar Spinach in Phase Three; splits back into Uzi Jesus - Gold Edition and Lord of Blight - Gold Edition."}},{id:"carl-eye-of-the-bedlam-bride-tattoo",name:"The Eye of the Bedlam Bride",owner:"carl",category:"wearable",description:"Shi Maria's fifth eye, tattooed onto Carl's chest with his own kit while she briefly controlled his body — the anchor that binds her to him permanently, in place of the card Donut tears up moments later.",glyphId:"eye-of-the-bedlam-bride",acquiredAtStopId:"floor-8-stop-19",spoiler:{book:6}},{id:"donut-the-experience-totem",name:"The Experience (T'Ghee totem)",owner:"donut",category:"other",description:"A wolf-bodied mob with a Che Guevara-caricature head, whose defeat drops the party's first T'Ghee card, three chapters before Geraldo becomes their first totem.",glyphId:"totem-the-experience",acquiredAtStopId:"floor-8-stop-3",spoiler:{book:6}},{id:"donut-heyzoos-totem",name:"HeyZoos / Uzi Jesus (T'Ghee totem)",owner:"donut",category:"other",description:"A unique undead ranged healer, gifted to Donut by a fellow crawler named Florin. Agrees to roughly half of whatever he's asked and lies about the rest.",glyphId:"totem-heyzoos",acquiredAtStopId:"floor-8-stop-9",spoiler:{book:6},fate:{status:"upgraded",spoiler:{book:6},note:"Fused permanently into Lazarus-A-Bang-Bang during the Phase Two deckmaster hunt; later returns as Uzi Jesus - Gold Edition."}},{id:"donut-jola-totem",name:"Jola (T'Ghee totem)",owner:"donut",category:"other",description:"A Yule Cat the size of a house, traded into Donut's deck from Katia's own.",glyphId:"totem-jola",acquiredAtStopId:"floor-8-stop-9",spoiler:{book:6}},{id:"donut-alpha-male-carl-totem",name:"Alpha Male Carl (T'Ghee totem)",owner:"donut",category:"other",description:"A masculine caricature of Carl himself, one of the Reminiscence Hydra's own totems, which Donut takes by accident after the fight.",glyphId:"totem-alpha-male-carl",acquiredAtStopId:"floor-8-stop-14",spoiler:{book:6},fate:{status:"destroyed",spoiler:{book:6},note:"Killed by Shi Maria when Donut's Golden Combo fusion misfires — the accident that binds Shi Maria to Carl instead."}},{id:"donut-leveled-up-frank-totem",name:"Leveled-Up Frank (T'Ghee totem)",owner:"donut",category:"other",description:"A revived copy of the dead crawler Frank Q, a Night Elf Blood Assassin, built for the Hydra fight but never played. Donut keeps him with Alpha Male Carl.",glyphId:"totem-leveled-up-frank",acquiredAtStopId:"floor-8-stop-14",spoiler:{book:6}},{id:"donut-skylar-spinach-totem",name:"Skylar Spinach (T'Ghee totem)",owner:"donut",category:"other",description:"Two fused entities carded as one — a bat-winged donkey head and a headless ghost snake — flagged en route to Asojano's shrine.",glyphId:"totem-skylar-spinach",acquiredAtStopId:"floor-8-stop-4",spoiler:{book:6}},{id:"carl-gloom-wraith-phase",name:"Gloom Wraith Phase",owner:"carl",category:"skill-book",rarity:"celestial",description:"A non-corporeal rush attack rolled from a Hell-Kissed Celestial Skill Potion of the Prince of Woe — a Floor 8 achievement box Carl finally opens in the Floor 9 safe room. Costs half his mana per burst.",glyphId:"potion-prince-of-woe",acquiredAtStopId:"floor-9-stop-2",spoiler:{book:7}},{id:"carl-mind-balance-toe-ring",name:"Enchanted Toe Ring of the Well-Balanced",owner:"carl",category:"wearable",rarity:"legendary",description:"Worn on the left pinky toe. Grants Heart, Mind, and Physical Balance at Level 5 each; Mind Balance blocks Enslavement and Conscription outright — the ring that keeps Shi Maria from seizing his body a second time. No source gives the ring a colour; the silver band and two-tone bead are editorial.",glyphId:"toe-ring-well-balanced",acquiredAtStopId:"floor-9-stop-2",spoiler:{book:7}},{id:"carl-reaper-spider-minion-patch",name:"Reaper Spider Minion Patch",owner:"carl",category:"other",rarity:"platinum",description:"A small upgrade patch granting Midnight Market access and merchant-proximity alerts — another Floor 8 achievement reward opened here, and the reason Carl can find the black market at all.",glyphId:"reaper-spider-minion-patch",acquiredAtStopId:"floor-9-stop-2",spoiler:{book:7}},{id:"donut-tiara-of-a-thousand-lights",name:"Tiara of a Thousand Lights",owner:"donut",category:"wearable",rarity:"celestial",description:"A bespoke Celestial Benefactor gift with 99 Absorption Jewel slots, each able to permanently drain a hat item's magic into the tiara. Charged repeatedly through the floor as Donut burns through borrowed headwear. No source gives the metal a colour; the silver is editorial.",glyphId:"tiara-of-a-thousand-lights",acquiredAtStopId:"floor-9-stop-2",spoiler:{book:7}},{id:"donut-cloak-of-the-benevolent-champion",name:"Cloak of the Benevolent Champion",owner:"donut",category:"wearable",rarity:"celestial",description:"Carl's own Floor 8 loot, handed to Donut instead of kept — a stat-matching cloak that drags her lowest base stat up to her highest. Timed to a Charisma potion the moment she first equips it, so it locks onto an inflated number and spends the floor dragging her fragile Constitution up to match.",glyphId:"cloak-benevolent-champion",acquiredAtStopId:"floor-9-stop-2",spoiler:{book:7}},{id:"party-planner",name:"Party Planner",owner:"party",category:"other",rarity:"celestial",description:"A Celestial airship awarded to Louis for surviving Ysalte's death-mark on the Ghosts of Earth floor. Louis flies it as Army Air General through the opening skirmishes.",glyphId:"party-planner",acquiredAtStopId:"floor-9-stop-4",spoiler:{book:7},fate:{status:"destroyed",spoiler:{book:7},note:"Destroyed by the drake Calliope; unrelated to the Reaver castle's later fall."}},{id:"carl-run-little-gunter-run",name:"Run, Little Günter, Run",owner:"carl",category:"spell-book",rarity:"legendary",description:"From Carl's own Legendary 1914 Box, the twin of the one that gave Donut War Crime(s) — both rewards for killing Empress D'Nadia. Cast inside Khepri's temple during Operation Snake Pit — the blast that kills everyone in the room but Carl, Khepri, and the temple-shielded Vinata.",glyphId:"tome-run-little-gunter",acquiredAtStopId:"floor-9-stop-6",spoiler:{book:7}},{id:"carl-hairbrush-of-the-beefmaster",name:"Enchanted Hairbrush of the Beefmaster",owner:"carl",category:"other",rarity:"celestial",description:"A reward for surviving ten gods at once inside Club Vanquisher. Five minutes of use grants thirty hours of Shining Charisma, a Speedster benefit, +25% Constitution, and a Level 10 Entourage spell.",glyphId:"hairbrush-beefmaster",acquiredAtStopId:"floor-9-stop-8",spoiler:{book:7}},{id:"donut-youre-not-done-yet",name:"You're Not Done Yet",owner:"donut",category:"spell-book",rarity:"legendary",description:"A quest reward Donut casts at tower-amplified range from the Nest, stripping the skin off a field of thousands of corpses to raise an army of undead Fleshers — a working the system itself logs as an Atrocity.",glyphId:"tome-youre-not-done-yet",acquiredAtStopId:"floor-9-stop-11",spoiler:{book:7}},{id:"donut-war-crimes-spell",name:"War Crime(s)",owner:"donut",category:"spell-book",rarity:"celestial",description:"An Atrocity-class spell, castable only three times ever and never without dropping the caster to 1% HP — channelled through her Astral Paw and a temporary Bijanbi tattoo as one giant astral cat's paw. Kills nearly every hostile left on the floor, including the feral god Meatus, and jumps her to Level 135. From Donut's own Legendary 1914 Box, the twin of the one that gave Carl Run, Little Günter, Run; first cast later on this same floor.",glyphId:"tome-war-crimes",acquiredAtStopId:"floor-9-stop-6",spoiler:{book:7}},{id:"donut-spiked-knee-pads-of-kina",name:"Enchanted Spiked Knee Pads of the Munificent Goddess Kina",owner:"donut",category:"wearable",rarity:"celestial",description:"Katia's own reward for the same ten-god survival that gave Carl his hairbrush. Katia eats a stack of magic items with its Iron Stomach effect to raise her own Intelligence, then hands the pads to Donut on her way out of the Dungeon for good.",glyphId:"knee-pads-of-kina",acquiredAtStopId:"floor-9-stop-21",spoiler:{book:7}},{id:"donut-assassin-of-sekhmet",name:"Assassin of Sekhmet",owner:"donut",category:"other",description:"Donut's class pick for Floor 10, taken through her Character Actor Skill. Grants pet accessories, the Smoke Form spell, a Healer's Grasp aura, and Oak Fell buffs — at the cost of provoking the god Khepri into forming a death cult in her name.",glyphId:"class-assassin-of-sekhmet",acquiredAtStopId:"floor-10-stop-1",spoiler:{book:8}},{id:"carl-big-shot-chicken-truck",name:"Big Shot Chicken Food Truck",owner:"party",category:"other",description:"A Prohibition-styled food truck Carl claims as the team's vehicle at the start of the floor — raced, upgraded, and lived in for all seven heats.",glyphId:"big-shot-chicken-truck",acquiredAtStopId:"floor-10-stop-1",spoiler:{book:8}},{id:"carl-oozy-form",name:"Oozy Form",owner:"carl",category:"spell-book",description:"Learned from a squirming, slime-covered spellbook between Heats 1 and 2. Transforms Carl into a slime — trading his eyes and ears for omnidirectional vision and darksight — and folds anything on his person, even another person or pet, into the slime with him for the duration.",glyphId:"tome-oozy-form",acquiredAtStopId:"floor-10-stop-3",spoiler:{book:8}},{id:"carl-macropus-dominus-skin",name:"Enchanted Juvenile Macropus Dominus Skin",owner:"carl",category:"wearable",description:"A kangaroo-corpse suit taken off a mechanical engineer the Lady Dominators drag out of Prison Pocket's pouch and kill, then hand to Carl under a temporary alliance. Grants Seeping Acid protection, a Level 10 Jump Skill, and +5 Lotion Application Skill — and locks Carl inside it for twelve hours once worn.",glyphId:"kangaroo-skin",acquiredAtStopId:"floor-10-stop-5",spoiler:{book:8},fate:{status:"lost",spoiler:{book:8},note:"A timed item; expires twelve hours after being worn."}},{id:"donut-assassins-veil",name:"The Assassin's Veil",owner:"donut",category:"wearable",description:"A unique, beaded headdress rewarded for the Assassin of Sekhmet class — female and Feline-only. +10% Dexterity, a Precognition Benefit that warns of nearby offensive-spell preparation, and marks the wearer hostile to any enemy of Sekhmet.",glyphId:"assassins-veil",acquiredAtStopId:"floor-10-stop-6",spoiler:{book:8}},{id:"donut-crupper-benevolent-champion",name:"Crupper of the Benevolent Champion",owner:"donut",category:"wearable",description:"The second piece of a four-piece matched set with the Cloak of the Benevolent Champion Donut already wears — boosting the Cloak's highest-matched stat by an extra 20%, raising Find Weakened to level 10, and letting one level-15 spell reach level 16. The underlying box traces back to a Floor 9 kill; Donut opens it here, in the safe room before Heat 2.",glyphId:"crupper-benevolent-champion",acquiredAtStopId:"floor-10-stop-6",spoiler:{book:8}},{id:"donut-wrap-sekhmet-compassion",name:"Wrap of Sekhmet's Compassion",owner:"other",category:"wearable",description:"A pet-only enchanted headband from the Assassin of Sekhmet reward set, given to Rend. Grants a once-daily invulnerability trigger plus a party heal within 3 metres whenever Donut drops below 10% health, and a 75% chance to raise a bootlicker on a fatal bite.",glyphId:"wrap-of-sekhmet",acquiredAtStopId:"floor-10-stop-6",spoiler:{book:8}},{id:"donut-nemes-pestilence",name:"Nemes of Pestilence",owner:"other",category:"wearable",description:"A pet-only enchanted hat from the same reward set, given to Mongo. Grants the same once-daily invulnerability trigger plus doubled Strength, and a 75% chance to inflict a Cruel Sepsis debuff on a fatal bite.",glyphId:"nemes-of-pestilence",acquiredAtStopId:"floor-10-stop-6",spoiler:{book:8}},{id:"carl-hotlist-expansion-potion",name:"Hotlist Expansion Potion",owner:"carl",category:"potion",rarity:"gold",description:"A small skill potion out of the Gold Payload Box Carl earned for the Bomb's Away Achievement — dumping every bomb he had at the end of Faction Wars. Expands his hotlist from ten slots to twenty.",glyphId:"potion-hotlist",acquiredAtStopId:"floor-10-stop-6",spoiler:{book:8}},{id:"carl-contingency",name:"Contingency",owner:"carl",category:"skill-book",rarity:"platinum",description:"Unlocked from a Platinum-tier hotlist potion in the lead-up to Heat 3. Adds a contingencies tab of up to ten automations chaining hotlist items to preset triggers — first put to use mid-race, an automatic health scroll saving him from a crash he never saw coming.",glyphId:"skill-contingency",acquiredAtStopId:"floor-10-stop-7",spoiler:{book:8}},{id:"carl-stage-performance-guild",name:"Stage Performance Guild Membership",owner:"carl",category:"other",description:`Permanent guild access earned for passing the Lollipop's karaoke entrance exam with "Take On Me" — and, per the guild's own perk, every other hidden guild on the floor now shows up on the map.`,glyphId:"stage-performance-guild",acquiredAtStopId:"floor-10-stop-12",spoiler:{book:8}},{id:"carl-stand-in-summons",name:"Stand-In Summons",owner:"carl",category:"other",description:"The reward for completing Dong Quixote's reunion quest — the AI grants Carl the right to choose two stand-ins of his own to send into the Floor 11 arena. Earned here, at the cost of the two lives the quest was meant to save; not spent until Floor 11.",glyphId:"stand-in-summons",acquiredAtStopId:"floor-10-stop-14",spoiler:{book:8}},{id:"donut-elite-gurkha-warrior-class",name:"Elite Gurkha Warrior Class",owner:"donut",category:"other",description:"Donut's class pick at the very start of the floor: a melee-focused specialty with a Perpetual Tank subclass and a big bump to her melee skills, which extends skills and gear to her whole crew — Gurkha hats for the hired mercenaries, blankets for the mounts, and kukri claw caps for Mongo.",glyphId:"class-elite-gurkha-warrior",acquiredAtStopId:"floor-11-stop-1",spoiler:{book:8}},{id:"donut-gurkha-hat",name:"Gurkha Hat",owner:"donut",category:"wearable",description:"Wide-brimmed and brown, granting bonuses to multiple skills at once — the class hat that comes with Elite Gurkha Warrior. Jamal and the parade's three giant mounts wear their own versions of the same hat.",glyphId:"gurkha-hat",acquiredAtStopId:"floor-11-stop-2",spoiler:{book:8}},{id:"carl-lucky-shot-patch",name:"Lucky Shot Patch",owner:"carl",category:"wearable",rarity:"legendary",description:"The Four-Leaf Clover Patch Carl earned on Floor 9, sewn onto a garment here for its Lucky Shot benefit: one fatal blow per floor gets deflected into a party member's body instead. Fires on Floor 11 itself, redirecting an Emberus incineration spell meant for Carl onto Penelope.",glyphId:"lucky-shot-patch",acquiredAtStopId:"floor-11-stop-2",spoiler:{book:8}},{id:"party-requite-dahlias",name:"Requite Dahlias",owner:"party",category:"other",description:"Flowers Donut grows with Sprout Forest in four colors — black, gold, magenta, and white — chosen to match the parade mounts' new blankets and hats, then fixed in place across the float with a gremlin-mixed potion.",glyphId:"requite-dahlia",acquiredAtStopId:"floor-11-stop-3",spoiler:{book:8}},{id:"party-parade-blankets",name:"Parade Blankets",owner:"other",category:"wearable",description:"Black-and-gold blankets fitted onto Sweety, Old Shuck, and Onikuma for the parade. Raise the big mounts' constitution by 20% and grant the Steady Charge skill, which seems to help them keep formation and walk in a straight line.",glyphId:"parade-blanket",acquiredAtStopId:"floor-11-stop-3",spoiler:{book:8}},{id:"carl-nothing-special-biscuit",name:"Enriched Pet Biscuit, 'Nothing Special Party Companion'",owner:"carl",category:"consumable",description:"An Enhanced Pet Biscuit earned back on Floor 10, its variant text leaving the recipient's body untouched — no ability to speak aloud, just full crawler status. Fed to Penelope in the arena, elevating her to a sapient party member.",glyphId:"biscuit-nothing-special",acquiredAtStopId:"floor-11-stop-9",spoiler:{book:8}},{id:"carl-mark-of-the-damned",name:"Mark of the Damned",owner:"carl",category:"other",description:"A pair of raised scars on the backs of Carl's hands, left behind when his deliberate renunciation of Emberus triggers an automatic smite and burns away the twin sun-disk tattoos that used to be there.",glyphId:"mark-of-the-damned",acquiredAtStopId:"floor-11-stop-12",spoiler:{book:8}},{id:"carl-splooge",name:"Splooge",owner:"carl",category:"potion",description:"Technically a potion but processed as a food-based buff — a staple against environmental hazards since Floor 10, one full gulp granting an hour of coverage. Doesn't confer the ability to breathe.",glyphId:"splooge-bucket",acquiredAtStopId:"floor-11-stop-11",spoiler:{book:8}},{id:"donut-bolt-of-ophiotaurus",name:"Bolt of Ophiotaurus",owner:"donut",category:"weapon",description:"One of a hundred ever made, originally Katia's from a Book 3 Benefactor Box. A successful strike to a god's eye pauses their invulnerability for fifteen seconds — Donut fires two of them through Emberus's own empty eye sockets, pinning him in place for Taranis to finish.",glyphId:"bolt-of-ophiotaurus",acquiredAtStopId:"floor-11-stop-13",spoiler:{book:8}},{id:"carl-banger-sphere",name:"Banger Sphere",owner:"carl",category:"consumable",description:"Bomb casing off an old Engineer's Table build, carried since the Iron Tangle. Combined with the wrong pet biscuit and launched into Scolopendra's mouth at The Puddle.",glyphId:"banger-sphere",acquiredAtStopId:"floor-11-stop-14",spoiler:{book:8}},{id:"carl-paramour-biscuit",name:"Enriched Pet Biscuit, 'The Paramour'",owner:"carl",category:"consumable",description:"Another Floor 10 earning, meant for someone else entirely — a permanent, incurable charm making the recipient fall hopelessly in love with whoever feeds it to them. Donut grabs it by mistake in the chaos of the inventory swap. It goes into Scolopendra's mouth with the bomb at The Puddle.",glyphId:"biscuit-paramour",acquiredAtStopId:"floor-11-stop-14",spoiler:{book:8}},{id:"carl-tracking-tag",name:"Tracking Tag",owner:"carl",category:"other",description:'A dart Carl finds lodged in his own leg after the fight, under the system message "The Kyryap has claimed you" — never explained anywhere on the page.',glyphId:"tracking-tag",acquiredAtStopId:"floor-11-stop-15",spoiler:{book:8}},{id:"party-emberus-memorial-crystal",name:"Memorial Crystal. Emberus.",owner:"party",category:"other",description:"A glowing, amber-hued gem Carl recovers half-buried in the arena dirt right after the fight — a second memorial crystal, this one bearing the dead god's own identity, taken up by the Royal Court once Taranis makes off with Prepotente's.",glyphId:"memorial-crystal-emberus",acquiredAtStopId:"floor-11-stop-15",spoiler:{book:8}},{id:"sexy-scolopendra-red-bow",name:"Red Bow",owner:"other",category:"wearable",description:"Sexy Scolopendra's only gear: a red bow tied to one of her two yellow antennae, present from the moment Donut's biscuit mistake first reduces the dungeon boss to a Level 1 crawler.",glyphId:"red-bow",acquiredAtStopId:"floor-11-stop-15",spoiler:{book:8}}];export{e as loot};
